class Solution { fun numOfArrays(n:Int,m:Int,k:Int):Int{val mod=1_000_000_007L;var dp=Array(k+1){LongArray(m+1)};for(maximum in 1..m)dp[1][maximum]=1;for(length in 2..n){val next=Array(k+1){LongArray(m+1)};for(cost in 1..k)for(maximum in 1..m){next[cost][maximum]=(next[cost][maximum]+dp[cost][maximum]*maximum)%mod;if(cost<k)for(newMax in maximum+1..m)next[cost+1][newMax]=(next[cost+1][newMax]+dp[cost][maximum])%mod};dp=next};return (dp[k].sum()%mod).toInt()} }
